"""Longest Valid Parentheses — stack holding the last invalid index.

The stack bottom is the index just before the current valid run, so the length
after a pop is i - stack[-1].

Time: O(n)   Space: O(n)
"""


class Solution:
    def longestValidParentheses(self, s: str) -> int:
        stack, best = [-1], 0
        for i, ch in enumerate(s):
            if ch == "(":
                stack.append(i)
            else:
                stack.pop()
                if stack:
                    best = max(best, i - stack[-1])
                else:
                    stack.append(i)      # new base for the next run
        return best
